INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Gilt das DRY-Prinzip nur für große Projekte?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Projekte profitieren"}, {"text": "Ja", "correct": false, "because": "Universell anwendbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit dem DRY-Prinzip?', 3, '[{"text": "Wiederholungen vermeiden", "correct": true, "because": "Einmalige Definition"}, {"text": "Code schneller machen", "correct": false, "because": "Nicht primär"}, {"text": "Mehr Features", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Techniken unterstützen das DRY-Prinzip?', 5, '[{"text": "Funktionen", "correct": true, "because": "Wiederverwendbare Logik"}, {"text": "Klassen", "correct": true, "because": "Zentralisierte Struktur"}, {"text": "Copy-Paste", "correct": false, "because": "Widerspricht DRY"}, {"text": "Globale Variablen", "correct": false, "because": "Keine Wiederverwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DRY reduziert Redundanz. b) Es verbietet ähnlichen Code.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ähnlichkeit erlaubt, wenn nicht redundant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim DRY-Prinzip?', 4, '[{"text": "Wiederverwendbarkeit", "correct": false, "because": "Kern des Prinzips"}, {"text": "Zentralisierung", "correct": false, "because": "Vermeidet Wiederholung"}, {"text": "Farbschema", "correct": true, "because": "Kein Code-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DRY mehr Funktionen erzeugt?', 2, '[{"text": "Ja", "correct": true, "because": "Logik wird ausgelagert"}, {"text": "Nein", "correct": false, "because": "Erhöht oft Anzahl"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel folgt dem DRY-Prinzip?', 3, '[{"text": "Funktion für wiederholte Logik", "correct": true, "because": "Einmal definiert"}, {"text": "Copy-Paste gleicher Code", "correct": false, "because": "Widerspricht DRY"}, {"text": "Inline-Code überall", "correct": false, "because": "Keine Wiederverwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet das DRY-Prinzip?', 5, '[{"text": "Wartbarkeit", "correct": true, "because": "Änderungen an einer Stelle"}, {"text": "Lesbarkeit", "correct": true, "because": "Weniger Redundanz"}, {"text": "Schnellere Ausführung", "correct": false, "because": "Kein Performance-Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) DRY spart Zeit. b) Es macht Code immer kürzer. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kürze nicht garantiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für das DRY-Prinzip?', 4, '[{"text": "Funktionen", "correct": false, "because": "Fördern Wiederverwendung"}, {"text": "Klassen", "correct": false, "because": "Zentralisieren Logik"}, {"text": "UI-Animationen", "correct": true, "because": "Kein Code-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist DRY ohne Refactoring möglich?', 2, '[{"text": "Ja", "correct": true, "because": "Von Anfang an umsetzbar"}, {"text": "Nein", "correct": false, "because": "Refactoring oft hilfreich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme löst das DRY-Prinzip?', 4, '[{"text": "Inkonsistenzen", "correct": true, "because": "Einheitliche Änderungen"}, {"text": "Wartungsaufwand", "correct": true, "because": "Weniger redundanter Code"}, {"text": "Langsame Tests", "correct": false, "because": "Kein Testfokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass DRY nur für Teams ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Solo nützlich"}, {"text": "Ja", "correct": false, "because": "Universell anwendbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich beim DRY-Prinzip?', 3, '[{"text": "Wiederverwendbarkeit", "correct": true, "because": "Einmalige Definition"}, {"text": "Schnelle Umsetzung", "correct": false, "because": "Qualität zählt"}, {"text": "Viele Kopien", "correct": false, "because": "Widerspricht DRY"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DRY fördert Konsistenz. b) Es verbietet ähnliche Logik.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ähnlichkeit erlaubt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat das DRY-Prinzip?', 5, '[{"text": "Höherer Abstraktionsaufwand", "correct": true, "because": "Funktionen brauchen Design"}, {"text": "Komplexere Logik", "correct": true, "because": "Zentralisierung kann schwierig sein"}, {"text": "Langsamere Ausführung", "correct": false, "because": "Kein Performance-Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist beim DRY-Prinzip unwichtig?', 3, '[{"text": "Wiederverwendung", "correct": false, "because": "Kernprinzip"}, {"text": "Konsistenz", "correct": false, "because": "Ziel von DRY"}, {"text": "Farbanimationen", "correct": true, "because": "Kein Code-Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Erhöht DRY die Komplexität?', 3, '[{"text": "Ja", "correct": true, "because": "Abstraktion kann komplexer sein"}, {"text": "Nein", "correct": false, "because": "Langfristig einfacher"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DRY Wartung erleichtert?', 2, '[{"text": "Ja", "correct": true, "because": "Änderungen an einer Stelle"}, {"text": "Nein", "correct": false, "because": "Wartbarkeit steigt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip ergänzt das DRY-Prinzip?', 4, '[{"text": "KISS", "correct": true, "because": "Einfachheit unterstützt"}, {"text": "YAGNI", "correct": false, "because": "Anderer Fokus"}, {"text": "LSP", "correct": false, "because": "Vererbungsspezifisch"}]');
